using System.Collections;
using System.Linq;
using BikiniWipeout.Core;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

namespace BikiniWipeout.Tests
{
    /// <summary>
    /// Phase 2B smoke tests for the imported cowgirl in Course_Foundation1_Cowgirl (generated by
    /// Bikini Wipeout > Phase 2B > Integrate Cowgirl). The scene is loaded by path in the editor, so it does
    /// not need to be in Build Settings. These check wiring, foot contact and the ragdoll round trip; they
    /// are not a substitute for watching the animation.
    /// </summary>
    public class CowgirlPlayTests
    {
        private const string ScenePath = "Assets/BikiniWipeout/Scenes/Course_Foundation1_Cowgirl.unity";

        private CourseManager course;
        private PlayerCharacter player;
        private Animator animator;
        private ScriptedInput input;

        [UnitySetUp]
        public IEnumerator LoadCourse()
        {
#if UNITY_EDITOR
            if (UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.SceneAsset>(ScenePath) == null)
            {
                Assert.Ignore("Cowgirl scene missing. Run: Bikini Wipeout > Phase 2B > Integrate Cowgirl.");
            }

            Time.timeScale = 1f;
            yield return UnityEditor.SceneManagement.EditorSceneManager.LoadSceneAsyncInPlayMode(
                ScenePath, new LoadSceneParameters(LoadSceneMode.Single));
            yield return null;
#else
            Assert.Ignore("Editor-only test.");
            yield break;
#endif
            course = CourseManager.Current;
            Assert.IsNotNull(course, "CourseManager");
            player = course.Player;
            Assert.IsNotNull(player, "Player");
            animator = player.AnimationState.GetComponent<Animator>();
            input = new ScriptedInput();
            player.Motor.InputSource = input;
        }

        [UnityTearDown]
        public IEnumerator Cleanup()
        {
            Time.timeScale = 1f;
            Cursor.lockState = CursorLockMode.None;
            Cursor.visible = true;
            yield return null;
        }

        private IEnumerator WaitUntil(System.Func<bool> condition, float timeoutSeconds, string what)
        {
            float deadline = Time.realtimeSinceStartup + timeoutSeconds;
            while (!condition())
            {
                if (Time.realtimeSinceStartup > deadline) Assert.Fail("Timed out after " + timeoutSeconds + " s waiting for: " + what);
                yield return null;
            }
        }

        private IEnumerator WaitForRunStart()
        {
            yield return WaitUntil(() => course.Session.Phase == CoursePhase.Running, 8f, "countdown to finish");
            yield return WaitUntil(() => player.Motor.IsGrounded, 3f, "player to stand on the start platform");
        }

        /// <summary>Lowest foot/toe bone height above the character root (the capsule's bottom).</summary>
        private float FootClearance()
        {
            float y = float.MaxValue;
            foreach (HumanBodyBones bone in new[] { HumanBodyBones.LeftFoot, HumanBodyBones.RightFoot, HumanBodyBones.LeftToes, HumanBodyBones.RightToes })
            {
                y = Mathf.Min(y, animator.GetBoneTransform(bone).position.y);
            }

            return y - player.transform.position.y;
        }

        [UnityTest]
        public IEnumerator Cowgirl_IsHumanoid_AndRagdollIsWired()
        {
            Assert.IsNotNull(animator, "Animator on Model");
            Assert.IsTrue(animator.isHuman, "Humanoid avatar");
            Assert.IsTrue(animator.avatar.isValid, "Valid avatar");
            Assert.AreEqual("Cowgirl", animator.runtimeAnimatorController.name, "Cowgirl controller");
            bool hasFaceUpParameter = false;
            foreach (AnimatorControllerParameter parameter in animator.parameters) hasFaceUpParameter |= parameter.name == "RecoveryFaceUp";
            Assert.IsTrue(hasFaceUpParameter, "RecoveryFaceUp parameter");
            Assert.AreEqual(2.1f, player.Knockdown.config.timings.RecoveryDuration, 0.001f, "Cowgirl recovery duration");
            Assert.IsNull(player.GetComponentInChildren<PlaceholderProceduralAnimator>(true), "Placeholder animator removed");
            Assert.AreEqual(11, player.Ragdoll.Bodies.Count, "11 ragdoll bodies");
            float mass = 0f;
            foreach (Rigidbody body in player.Ragdoll.Bodies) mass += body.mass;
            Assert.AreEqual(61f, mass, 0.01f, "Total ragdoll mass");
            Assert.AreEqual(animator.GetBoneTransform(HumanBodyBones.Hips), player.Ragdoll.RootBody.transform);
            foreach (Rigidbody body in player.Ragdoll.Bodies)
            {
                Assert.AreEqual(GameLayers.Ragdoll, body.gameObject.layer, body.name + " layer");
                Assert.IsNotNull(body.GetComponent<Collider>(), body.name + " collider");
            }

            yield return null;
        }

        [UnityTest]
        public IEnumerator Cowgirl_StandsWalksRuns_WithFeetOnTheGround()
        {
            yield return WaitForRunStart();
            yield return new WaitForSeconds(0.5f);
            Assert.AreEqual(CharacterAnimState.Idle, player.AnimationState.CurrentState);
            float idleFeet = FootClearance();
            Assert.That(idleFeet, Is.InRange(-0.05f, 0.2f), "Idle: feet should rest on the ground (not float or sink).");
            float hipsHeight = animator.GetBoneTransform(HumanBodyBones.Hips).position.y - player.transform.position.y;
            Assert.That(hipsHeight, Is.InRange(0.75f, 1.0f), "Idle: hips at standing height.");

            input.Move = new Vector2(0f, 1f);
            yield return new WaitForSeconds(1f);
            Assert.AreEqual(CharacterAnimState.Walk, player.AnimationState.CurrentState);
            Assert.That(FootClearance(), Is.InRange(-0.05f, 0.3f), "Walk: feet near ground.");

            input.RunHeld = true;
            yield return new WaitForSeconds(1f);
            Assert.AreEqual(CharacterAnimState.Run, player.AnimationState.CurrentState);
            Assert.That(FootClearance(), Is.InRange(-0.05f, 0.4f), "Run: feet near ground.");
            input.Move = Vector2.zero;
            input.RunHeld = false;
        }

        // ------------------------------------------------------------------ gait quality (Phase 2B locomotion)

        private struct Gait
        {
            public float speed, slideMedian, slideRatio, stanceSlide, stanceRatio, varusMax, kneeYawAbs, facing, ankleGap;
            public int frames, stanceFrames;
            public override string ToString() =>
                $"body {speed:F2} m/s | STANCE foot slide median {stanceSlide:F2} m/s ({stanceRatio:P0} of body, {stanceFrames} samples) | " +
                $"lower-foot slide (incl. swing/flight) {slideMedian:F2} m/s ({slideRatio:P0}) | knee bow-out max {varusMax:F1}% of leg | " +
                $"bent-knee direction |avg| {kneeYawAbs:F0}° | ankle gap {ankleGap:F2} of leg | hips facing travel {facing:F2} | {frames} frames";
        }

        /// <summary>Moves diagonally across the empty start platform and measures the gait on her actual skeleton.</summary>
        private IEnumerator MeasureGait(bool run, System.Action<Gait> result)
        {
            Vector3 dir = new Vector3(0.63f, 0f, 0.77f).normalized;
            player.Motor.Teleport(new Vector3(-4.3f, 0.02f, -5.3f), Quaternion.LookRotation(dir));
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "grounded after teleport");
            Vector3 camForward = Vector3.ProjectOnPlane(Camera.main.transform.forward, Vector3.up).normalized;
            Vector3 camRight = Vector3.Cross(Vector3.up, camForward);
            input.Move = new Vector2(Vector3.Dot(dir, camRight), Vector3.Dot(dir, camForward)).normalized;
            input.RunHeld = run;
            yield return new WaitForSeconds(run ? 0.45f : 0.6f); // reach steady speed

            Transform root = player.transform;
            Transform[] toes = { animator.GetBoneTransform(HumanBodyBones.LeftToes), animator.GetBoneTransform(HumanBodyBones.RightToes) };
            var slides = new System.Collections.Generic.List<float>();
            float varusMax = 0f, yawSum = 0f, facingSum = 0f, speedSum = 0f, gapSum = 0f; int yawN = 0, n = 0;
            int lastPlanted = -1; Vector3 lastPlantedPos = Vector3.zero;
            var stance = new[] { new System.Collections.Generic.List<(float h, float v)>(), new System.Collections.Generic.List<(float h, float v)>() };
            var lastToe = new Vector3?[2];
            float end = Time.time + (run ? 1.1f : 1.6f);
            while (Time.time < end)
            {
                yield return null;
                float dt = Time.deltaTime; if (dt <= 0f) continue;
                n++;
                speedSum += player.Motor.PlanarSpeed;
                int planted = toes[0].position.y < toes[1].position.y ? 0 : 1;
                Vector3 p = toes[planted].position;
                if (planted == lastPlanted)
                    slides.Add(Vector3.ProjectOnPlane(p - lastPlantedPos, Vector3.up).magnitude / dt);
                lastPlanted = planted; lastPlantedPos = p;

                // Stance-only samples: each foot's horizontal speed together with its height above the ground.
                for (int f = 0; f < 2; f++)
                {
                    Vector3 fp = toes[f].position;
                    if (lastToe[f].HasValue)
                        stance[f].Add((fp.y - root.position.y, Vector3.ProjectOnPlane(fp - lastToe[f].Value, Vector3.up).magnitude / dt));
                    lastToe[f] = fp;
                }

                foreach (bool left in new[] { true, false })
                {
                    Vector3 h = root.InverseTransformPoint(animator.GetBoneTransform(left ? HumanBodyBones.LeftUpperLeg : HumanBodyBones.RightUpperLeg).position);
                    Vector3 k = root.InverseTransformPoint(animator.GetBoneTransform(left ? HumanBodyBones.LeftLowerLeg : HumanBodyBones.RightLowerLeg).position);
                    Vector3 a = root.InverseTransformPoint(animator.GetBoneTransform(left ? HumanBodyBones.LeftFoot : HumanBodyBones.RightFoot).position);
                    float leg = (k - h).magnitude + (a - k).magnitude;
                    Vector3 line = a - h;
                    Vector3 off = k - (h + line * (Vector3.Dot(k - h, line) / line.sqrMagnitude));
                    float outward = left ? -1f : 1f;
                    varusMax = Mathf.Max(varusMax, off.x * outward / leg * 100f);
                    if (Vector3.Angle(k - h, a - k) > 15f && off.magnitude > 0.01f * leg)
                    {
                        yawSum += Mathf.Abs(Mathf.Atan2(off.x * outward, off.z) * Mathf.Rad2Deg);
                        yawN++;
                    }
                }

                Vector3 la = root.InverseTransformPoint(animator.GetBoneTransform(HumanBodyBones.LeftFoot).position);
                Vector3 ra = root.InverseTransformPoint(animator.GetBoneTransform(HumanBodyBones.RightFoot).position);
                Vector3 lh = root.InverseTransformPoint(animator.GetBoneTransform(HumanBodyBones.LeftUpperLeg).position);
                Vector3 lk = root.InverseTransformPoint(animator.GetBoneTransform(HumanBodyBones.LeftLowerLeg).position);
                gapSum += Mathf.Abs(la.x - ra.x) / ((lk - lh).magnitude + (la - lk).magnitude);
                Vector3 hipsForward = Vector3.ProjectOnPlane(animator.GetBoneTransform(HumanBodyBones.Hips).forward, Vector3.up).normalized;
                facingSum += Vector3.Dot(hipsForward, dir);
            }

            input.Move = Vector2.zero; input.RunHeld = false;
            slides.Sort();
            var g = new Gait
            {
                speed = speedSum / n, slideMedian = slides.Count > 0 ? slides[slides.Count / 2] : 0f, varusMax = varusMax,
                kneeYawAbs = yawN > 0 ? yawSum / yawN : 0f, facing = facingSum / n, ankleGap = gapSum / n, frames = n,
            };
            g.slideRatio = g.speed > 0.01f ? g.slideMedian / g.speed : 0f;

            // Planted = the toe within 3 cm of that foot's lowest height in this run (real ground contact only;
            // swing and flight phases are excluded).
            var stanceSpeeds = new System.Collections.Generic.List<float>();
            foreach (var samples in stance)
            {
                if (samples.Count == 0) continue;
                float floor = float.MaxValue;
                foreach (var s in samples) floor = Mathf.Min(floor, s.h);
                foreach (var s in samples) if (s.h <= floor + 0.03f) stanceSpeeds.Add(s.v);
            }

            stanceSpeeds.Sort();
            g.stanceSlide = stanceSpeeds.Count > 0 ? stanceSpeeds[stanceSpeeds.Count / 2] : 0f;
            g.stanceRatio = g.speed > 0.01f ? g.stanceSlide / g.speed : 0f;
            g.stanceFrames = stanceSpeeds.Count;
            result(g);
        }

        [UnityTest]
        public IEnumerator Cowgirl_Gait_LegsAligned_FeetPlanted_WalkAndRun()
        {
            yield return WaitForRunStart();
            Gait walk = default, run = default;
            yield return MeasureGait(false, g => walk = g);
            yield return MeasureGait(true, g => run = g);
            Debug.Log("[CowgirlGait] WALK " + walk);
            Debug.Log("[CowgirlGait] RUN  " + run);

            foreach ((string name, Gait g) in new[] { ("Walk", walk), ("Run", run) })
            {
                Assert.Less(g.varusMax, 6f, name + ": knees bowing outward (bow-legged).");
                Assert.Less(g.kneeYawAbs, 30f, name + ": bent knees should point forward, not sideways.");
                // Foot slide is logged above but not asserted: it is sampled per rendered frame, so it depends on the
                // frame rate (≈20% of body speed at ~70 fps vs ≈37% at ~25 fps in a loaded full-suite run). Judge it
                // visually. The knee and facing metrics are frame-rate independent and identical in both cases.
                Assert.Greater(g.facing, 0.9f, name + ": hips should face the direction of travel.");
            }
        }

        private struct Motion
        {
            public float speed, meanX, meanZ, swayX, surgeZ, bobY, pelvisYaw, pelvisRoll, counterRot, varusMax, kneeYawAbs, walkWeight;
            public override string ToString() =>
                $"body {speed:F2} m/s | walk-clip weight {walkWeight:P0} | pelvis sway (side) {swayX * 100f:F1} cm, surge (fwd) {surgeZ * 100f:F1} cm, mean offset x/z {meanX * 100f:F1}/{meanZ * 100f:F1} cm, " +
                $"bob {bobY * 100f:F1} cm | pelvis yaw range {pelvisYaw:F1}°, roll range {pelvisRoll:F1}° | shoulder-vs-pelvis counter-rotation range {counterRot:F1}° | " +
                $"knee bow-out max {varusMax:F1}% | bent-knee direction |avg| {kneeYawAbs:F0}°";
        }

        /// <summary>Walks straight across the start platform at a given stick deflection and profiles the body motion
        /// in the character's own frame (what the camera sees, independent of where she is).</summary>
        private IEnumerator MeasureMotion(float stick, System.Action<Motion> result)
        {
            Vector3 dir = new Vector3(0.63f, 0f, 0.77f).normalized;
            player.Motor.Teleport(new Vector3(-4.3f, 0.02f, -5.3f), Quaternion.LookRotation(dir));
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "grounded after teleport");
            Vector3 camForward = Vector3.ProjectOnPlane(Camera.main.transform.forward, Vector3.up).normalized;
            input.Move = new Vector2(Vector3.Dot(dir, Vector3.Cross(Vector3.up, camForward)), Vector3.Dot(dir, camForward)).normalized * stick;
            yield return new WaitForSeconds(0.6f);

            Transform root = player.transform;
            Vector3 P(HumanBodyBones b) => root.InverseTransformPoint(animator.GetBoneTransform(b).position);
            float xMin = float.MaxValue, xMax = float.MinValue, zMin = float.MaxValue, zMax = float.MinValue, yMin = float.MaxValue, yMax = float.MinValue;
            float yawMin = float.MaxValue, yawMax = float.MinValue, rollMin = float.MaxValue, rollMax = float.MinValue, crMin = float.MaxValue, crMax = float.MinValue;
            var m = new Motion(); float yawSum = 0f; int yawN = 0, n = 0;
            float end = Time.time + 2.4f;
            while (Time.time < end)
            {
                yield return null;
                n++;
                m.speed += player.Motor.PlanarSpeed;
                foreach (AnimatorClipInfo info in animator.GetCurrentAnimatorClipInfo(0))
                    if (info.clip.name.StartsWith("Cowgirl_Walk")) m.walkWeight += info.weight;
                Vector3 hips = P(HumanBodyBones.Hips);
                m.meanX += hips.x; m.meanZ += hips.z;
                xMin = Mathf.Min(xMin, hips.x); xMax = Mathf.Max(xMax, hips.x); zMin = Mathf.Min(zMin, hips.z); zMax = Mathf.Max(zMax, hips.z); yMin = Mathf.Min(yMin, hips.y); yMax = Mathf.Max(yMax, hips.y);
                Vector3 hl = P(HumanBodyBones.LeftUpperLeg), hr = P(HumanBodyBones.RightUpperLeg), hp = hr - hl;
                Vector3 sh = P(HumanBodyBones.RightUpperArm) - P(HumanBodyBones.LeftUpperArm);
                float yaw = Mathf.Atan2(-hp.z, hp.x) * Mathf.Rad2Deg, roll = Mathf.Atan2(hp.y, new Vector2(hp.x, hp.z).magnitude) * Mathf.Rad2Deg;
                float cr = Mathf.DeltaAngle(yaw, Mathf.Atan2(-sh.z, sh.x) * Mathf.Rad2Deg);
                yawMin = Mathf.Min(yawMin, yaw); yawMax = Mathf.Max(yawMax, yaw); rollMin = Mathf.Min(rollMin, roll); rollMax = Mathf.Max(rollMax, roll); crMin = Mathf.Min(crMin, cr); crMax = Mathf.Max(crMax, cr);
                foreach (bool left in new[] { true, false })
                {
                    Vector3 h = left ? hl : hr;
                    Vector3 k = P(left ? HumanBodyBones.LeftLowerLeg : HumanBodyBones.RightLowerLeg), a = P(left ? HumanBodyBones.LeftFoot : HumanBodyBones.RightFoot);
                    float leg = (k - h).magnitude + (a - k).magnitude; Vector3 line = a - h;
                    Vector3 off = k - (h + line * (Vector3.Dot(k - h, line) / line.sqrMagnitude));
                    float outward = left ? -1f : 1f;
                    m.varusMax = Mathf.Max(m.varusMax, off.x * outward / leg * 100f);
                    if (Vector3.Angle(k - h, a - k) > 15f && off.magnitude > 0.01f * leg) { yawSum += Mathf.Abs(Mathf.Atan2(off.x * outward, off.z) * Mathf.Rad2Deg); yawN++; }
                }
            }

            input.Move = Vector2.zero;
            m.speed /= n; m.walkWeight /= n; m.meanX /= n; m.meanZ /= n; m.kneeYawAbs = yawN > 0 ? yawSum / yawN : 0f;
            m.swayX = xMax - xMin; m.surgeZ = zMax - zMin; m.bobY = yMax - yMin;
            m.pelvisYaw = yawMax - yawMin; m.pelvisRoll = rollMax - rollMin; m.counterRot = crMax - crMin;
            result(m);
        }

        /// <summary>The Female Walk clip only plays below the jog speed (gamepad half-stick, or a lower walkSpeed).
        /// Guards that the real walk clip keeps her legs aligned and keeps the authored weight shift.</summary>
        [UnityTest]
        public IEnumerator Cowgirl_WalkPace_LegsAligned_NaturalPelvis()
        {
            yield return WaitForRunStart();
            float walkSpeed = player.Motor.Config.walkSpeed;
            foreach (float speed in new[] { 1.3f, 1.5f, 1.8f, walkSpeed }.Where(s => s <= walkSpeed + 0.001f).Distinct())
            {
                Motion m = default;
                yield return MeasureMotion(Mathf.Clamp01(speed / walkSpeed), r => m = r);
                Debug.Log($"[CowgirlWalk] target {speed:F1} m/s: " + m);
                Assert.Less(m.varusMax, 6f, $"{speed:F1} m/s: knees bowing outward (bow-legged).");
                Assert.Less(m.kneeYawAbs, 30f, $"{speed:F1} m/s: bent knees should point forward, not sideways.");
                if (speed <= 1.55f) // includes the walk key at walkSpeed 1.5
                {
                    Assert.Greater(m.walkWeight, 0.9f, "At a walking pace the Female Walk clip should dominate.");
                    Assert.Greater(m.pelvisYaw, 3f, "Walk: pelvis should rotate with the stride (not locked).");
                    // Authored side-to-side weight shift is ~4.7 cm on her body; it was 1.3 cm when discarded with root motion.
                    Assert.Greater(m.swayX, 0.03f, "Walk: pelvis should shift weight side to side over the stance foot.");
                }
            }
        }

        [UnityTest]
        public IEnumerator Cowgirl_Animator_UsesLocomotionBlend_AndLandsIntoIt()
        {
            yield return WaitForRunStart();
            // Clear 14 m diagonal across the start platform.
            Vector3 dir = new Vector3(0.63f, 0f, 0.77f).normalized;
            player.Motor.Teleport(new Vector3(-4.3f, 0.02f, -5.3f), Quaternion.LookRotation(dir));
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "grounded after teleport");
            Vector3 camForward = Vector3.ProjectOnPlane(Camera.main.transform.forward, Vector3.up).normalized;
            input.Move = new Vector2(Vector3.Dot(dir, Vector3.Cross(Vector3.up, camForward)), Vector3.Dot(dir, camForward)).normalized;
            yield return new WaitForSeconds(0.5f);
            Assert.IsTrue(animator.GetCurrentAnimatorStateInfo(0).IsName("Locomotion"), "Walking plays the Locomotion blend tree.");
            input.RunHeld = true;
            yield return new WaitForSeconds(0.35f);
            Assert.IsTrue(animator.GetCurrentAnimatorStateInfo(0).IsName("Locomotion"), "Running stays in the same blend tree (no cross-fade pop).");

            // Running jump: must flow back into locomotion, not stop in Idle.
            input.JumpPressedThisFrame = true; input.JumpHeld = true;
            yield return null;
            input.JumpPressedThisFrame = false;
            yield return WaitUntil(() => !player.Motor.IsGrounded, 1f, "take-off");
            yield return WaitUntil(() => player.Motor.IsGrounded, 3f, "landing");
            input.JumpHeld = false;
            bool sawIdle = false;
            float until = Time.time + 0.6f;
            while (Time.time < until)
            {
                sawIdle |= animator.GetCurrentAnimatorStateInfo(0).IsName("Idle");
                yield return null;
            }

            input.Move = Vector2.zero; input.RunHeld = false;
            Assert.IsFalse(sawIdle, "Landing while running should not pass through Idle.");
        }

        // Ragdoll falls are chaotic, so each test tries a few pushes until she genuinely lands on the wanted side,
        // then requires the matching get-up to play. Fails if that side is never reached.
        [UnityTest]
        public IEnumerator Cowgirl_Knockdown_FaceDown_PlaysFaceDownGetUp() => KnockdownUntilSide(false, new[]
        {
            new Vector3(0f, 0.5f, 0.75f), new Vector3(0f, 0.2f, 1.6f), new Vector3(0f, 0f, 2.4f), new Vector3(0f, 0.6f, 3f),
        });

        [UnityTest]
        public IEnumerator Cowgirl_Knockdown_FaceUp_PlaysFaceUpGetUp() => KnockdownUntilSide(true, new[]
        {
            new Vector3(0f, 0.5f, -0.75f), new Vector3(0f, 0.2f, -1.6f), new Vector3(0f, 0f, -2.4f), new Vector3(0f, 0.6f, -3f),
        });

        private IEnumerator KnockdownUntilSide(bool wantFaceUp, Vector3[] launches)
        {
            yield return WaitForRunStart();
            foreach (Vector3 launch in launches)
            {
                player.Motor.Teleport(new Vector3(0f, 0.02f, -2f), Quaternion.identity);
                yield return WaitUntil(() => player.Motor.IsGrounded && !player.Knockdown.IsImmune, 4f, "standing, not immune");
                yield return new WaitForSeconds(0.2f);
                yield return KnockdownRoundTrip(launch);
                if (player.Knockdown.RecoveryFaceUp == wantFaceUp) yield break;
            }

            Assert.Fail("Never landed " + (wantFaceUp ? "face up" : "face down") + "; the matching get-up was not exercised.");
        }

        private IEnumerator KnockdownRoundTrip(Vector3 launch)
        {
            Transform hips = animator.GetBoneTransform(HumanBodyBones.Hips);
            Transform head = animator.GetBoneTransform(HumanBodyBones.Head);
            float restSpan = Vector3.Distance(hips.position, head.position);

            bool recovered = false, sawGetUp = false;
            float recoveringSince = -1f;
            player.Knockdown.Recovered += () => recovered = true;
            Assert.IsTrue(player.Knockdown.ForceKnockdown(launch, player.FocusPosition));
            Assert.IsTrue(player.Ragdoll.IsActive, "Ragdoll should be simulated.");
            Assert.IsFalse(animator.enabled, "Animator off while ragdolled.");

            float deadline = Time.time + 12f;
            while (player.Knockdown.IsDown && Time.time < deadline)
            {
                foreach (Rigidbody body in player.Ragdoll.Bodies)
                {
                    Vector3 p = body.position;
                    Assert.IsFalse(float.IsNaN(p.x) || float.IsNaN(p.y) || float.IsNaN(p.z), body.name + " position is NaN");
                }

                Assert.Less(Vector3.Distance(hips.position, head.position), restSpan * 1.25f, "Spine/neck joints must not stretch apart.");

                if (player.Knockdown.Phase == KnockdownPhase.Recovering && recoveringSince < 0f) recoveringSince = Time.time;
                if (recoveringSince >= 0f && !sawGetUp && Time.time - recoveringSince > 0.45f)
                {
                    // Past the ragdoll pose blend: the get-up clip owns the pose and must match the lying side.
                    sawGetUp = true;
                    string expected = player.Knockdown.RecoveryFaceUp ? "RecoverFaceUp" : "RecoverFaceDown";
                    Assert.IsTrue(animator.GetCurrentAnimatorStateInfo(0).IsName(expected), "Animator should be in " + expected);
                    float hipsHeight = hips.position.y - player.transform.position.y;
                    Assert.Less(hipsHeight, 0.6f, "Early in the get-up the hips should still be low (clip is playing, not idle).");
                }

                yield return null;
            }

            Debug.Log("[CowgirlTest] launch " + launch + " -> RecoveryFaceUp=" + player.Knockdown.RecoveryFaceUp);
            Assert.IsTrue(sawGetUp, "Get-up animation should have been observed.");
            Assert.IsTrue(recovered, "Cowgirl should recover (not rescued).");
            Assert.IsTrue(animator.enabled, "Animator back on after recovery.");
            Assert.IsTrue(player.Motor.ControlEnabled);
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "player to stand after recovery");
            yield return new WaitForSeconds(0.5f);
            Assert.That(FootClearance(), Is.InRange(-0.05f, 0.25f), "After recovery: feet back on the ground.");
        }

        /// <summary>
        /// Phase 2C: the mesh must stay on the capsule through takeoff, flight and landing. Before the fix the landing
        /// clip kept its authored mid-course offset and put her body 2.8 m ahead of the capsule, and the jump clip
        /// dropped her body 8–13 cm at takeoff.
        /// </summary>
        [UnityTest]
        public IEnumerator Cowgirl_Jump_MeshStaysOnCapsule_NoSnap([Values(0f, 1f, 2f)] float mode)
        {
            yield return WaitForRunStart();
            Vector3 dir = new Vector3(0.63f, 0f, 0.77f).normalized;
            player.Motor.Teleport(new Vector3(-4.3f, 0.02f, -5.3f), Quaternion.LookRotation(dir));
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "grounded after teleport");
            Vector3 camForward = Vector3.ProjectOnPlane(Camera.main.transform.forward, Vector3.up).normalized;
            bool moving = mode > 0f;
            input.Move = moving ? new Vector2(Vector3.Dot(dir, Vector3.Cross(Vector3.up, camForward)), Vector3.Dot(dir, camForward)).normalized : Vector2.zero;
            input.RunHeld = mode > 1f;
            yield return new WaitForSeconds(0.7f);

            Transform root = player.transform, hips = animator.GetBoneTransform(HumanBodyBones.Hips);
            var samples = new System.Collections.Generic.List<(float t, Vector3 p)>();
            input.JumpPressedThisFrame = true; input.JumpHeld = true;
            yield return null;
            input.JumpPressedThisFrame = false;
            bool left = false; float landedAt = -1f, end = Time.time + 3f;
            while (Time.time < end && (landedAt < 0f || Time.time - landedAt < 0.6f))
            {
                left |= !player.Motor.IsGrounded;
                if (left && player.Motor.IsGrounded && landedAt < 0f) landedAt = Time.time;
                samples.Add((Time.time, root.InverseTransformPoint(hips.position)));
                yield return null;
            }

            input.JumpHeld = false; input.Move = Vector2.zero; input.RunHeld = false;
            Assert.Greater(landedAt, 0f, "Should land.");
            float maxHorizontal = 0f, maxShift = 0f;
            for (int i = 0; i < samples.Count; i++)
            {
                maxHorizontal = Mathf.Max(maxHorizontal, new Vector2(samples[i].p.x, samples[i].p.z).magnitude);
                for (int j = i + 1; j < samples.Count && samples[j].t - samples[i].t <= 0.08f; j++)
                    maxShift = Mathf.Max(maxShift, (samples[j].p - samples[i].p).magnitude);
            }

            Debug.Log($"[CowgirlJump] {(mode > 1f ? "sprint" : moving ? "walk" : "standing")}: hips max horizontal offset from capsule {maxHorizontal * 100f:F1} cm, " +
                      $"largest body shift within 80 ms {maxShift * 100f:F1} cm");
            Assert.Less(maxHorizontal, 0.2f, "Mesh must stay over the capsule (no teleport).");
            Assert.Less(maxShift, 0.12f, "No visible snap of the body relative to the capsule.");
        }

        [UnityTest]
        public IEnumerator Cowgirl_Sprint_PlaysFastRun_LegsAligned()
        {
            yield return WaitForRunStart();
            Vector3 dir = new Vector3(0.63f, 0f, 0.77f).normalized;
            player.Motor.Teleport(new Vector3(-4.3f, 0.02f, -5.3f), Quaternion.LookRotation(dir));
            yield return WaitUntil(() => player.Motor.IsGrounded, 2f, "grounded after teleport");
            Vector3 camForward = Vector3.ProjectOnPlane(Camera.main.transform.forward, Vector3.up).normalized;
            input.Move = new Vector2(Vector3.Dot(dir, Vector3.Cross(Vector3.up, camForward)), Vector3.Dot(dir, camForward)).normalized;
            input.RunHeld = true;
            yield return new WaitForSeconds(0.8f);
            float sprintWeight = 0f; int n = 0;
            float end = Time.time + 0.6f;
            while (Time.time < end)
            {
                yield return null; n++;
                foreach (AnimatorClipInfo info in animator.GetCurrentAnimatorClipInfo(0))
                    if (info.clip.name == "Cowgirl_Sprint") sprintWeight += info.weight;
            }

            input.Move = Vector2.zero; input.RunHeld = false;
            sprintWeight /= n;
            Debug.Log($"[CowgirlSprint] Fast Run weight at {player.Motor.Config.runSpeed:F1} m/s: {sprintWeight:P0}");
            Assert.Greater(sprintWeight, 0.95f, "Sprinting should play the Fast Run, not a sped-up jog.");
        }

        [UnityTest]
        public IEnumerator Cowgirl_Jumps_ThroughJumpAndFallStates()
        {
            yield return WaitForRunStart();
            bool sawJump = false, sawFall = false;
            input.JumpPressedThisFrame = true;
            input.JumpHeld = true;
            yield return null;
            input.JumpPressedThisFrame = false;
            float deadline = Time.time + 2.5f;
            bool left = false;
            while (Time.time < deadline)
            {
                sawJump |= player.AnimationState.CurrentState == CharacterAnimState.Jump;
                if (player.AnimationState.CurrentState == CharacterAnimState.Fall && player.AnimationState.TimeInState > 0.15f)
                {
                    sawFall = true;
                    // Falling Idle is authored yawed ~43°; root rotation from the body must keep her facing forward.
                    Vector3 hipsForward = Vector3.ProjectOnPlane(animator.GetBoneTransform(HumanBodyBones.Hips).forward, Vector3.up).normalized;
                    Assert.Greater(Vector3.Dot(hipsForward, player.transform.forward), 0.85f, "Fall pose should face the travel direction.");
                }
                left |= !player.Motor.IsGrounded;
                if (left && player.Motor.IsGrounded) break;
                yield return null;
            }

            input.JumpHeld = false;
            Assert.IsTrue(sawJump, "Jump state");
            Assert.IsTrue(sawFall, "Fall state");
            Assert.IsTrue(player.Motor.IsGrounded, "Landed");
        }
    }
